import Foundation
import Sparkle

/// Sparkle auto-updates. The appcast lives on the GitHub release; updates are
/// EdDSA-signed with the key generated by Sparkle's `generate_keys`.
/// Sandboxed: uses Sparkle's installer-launcher and downloader XPC services,
/// so the app itself still has no network entitlement.
@MainActor
final class UpdaterService {
    static let shared = UpdaterService()
    private let controller: SPUStandardUpdaterController

    private init() {
        controller = SPUStandardUpdaterController(startingUpdater: true, updaterDelegate: nil, userDriverDelegate: nil)
    }

    var canCheck: Bool { controller.updater.canCheckForUpdates }
    func checkForUpdates() { controller.checkForUpdates(nil) }
    var automaticallyChecks: Bool {
        get { controller.updater.automaticallyChecksForUpdates }
        set { controller.updater.automaticallyChecksForUpdates = newValue }
    }
}
